  'discipline'=>['enabled'=>false,'schedule'=>'immediate','template'=>'ولی گرامی {student}، گزارش انضباطی «{title}» در {date} ثبت شد. لطفاً با مدرسه تماس بگیرید.'],
  'daily_grades'=>['enabled'=>false,'time'=>'18:00','template'=>'خلاصه عملکرد روزانه {student}: {summary}'],
  'weekly_grades'=>['enabled'=>false,'weekday'=>'5','time'=>'18:00','template'=>'خلاصه عملکرد هفتگی {student}: {summary}'],
  'monthly_grades'=>['enabled'=>false,'day'=>'1','time'=>'18:00','template'=>'خلاصه عملکرد ماهانه {student}: {summary}'],
  'module_grades'=>['enabled'=>false,'template'=>'نتیجه {module} درس {course} برای {student}: {summary}'],
