function sms_config(): array {
 $defaults=['provider'=>'farazsms','enabled'=>false,'otp_enabled'=>false,'api_key'=>'','line_number'=>'','service_line'=>'','otp_pattern'=>'y5ZP3dLFs5','otp_attribute'=>'code','school_name'=>'دفتر کلاسی من','send_limit'=>500,'quiet_from'=>'21:00','quiet_to'=>'07:00','cron_token'=>'','rules'=>sms_rule_defaults()];
 $file=__DIR__.'/sms-config.php';$saved=is_file($file)?require $file:[];if(!is_array($saved))$saved=[];$config=array_replace($defaults,$saved);$config['rules']=array_replace_recursive(sms_rule_defaults(),is_array($saved['rules']??null)?$saved['rules']:[]);return $config;
}
function sms_public_config(): array {$c=sms_config();$configured=$c['enabled']&&$c['api_key']!==''&&($c['line_number']!==''||$c['service_line']!=='');return ['configured'=>$configured,'otpEnabled'=>(bool)($c['enabled']&&$c['otp_enabled']),'provider'=>'farazsms','message'=>$configured?'سامانه پیامک آماده است':'تنظیمات فراز اس‌ام‌اس کامل نشده است'];}
function sms_safe_config(array $c): array {return ['provider'=>'farazsms','enabled'=>(bool)$c['enabled'],'otpEnabled'=>(bool)$c['otp_enabled'],'lineNumber'=>$c['line_number'],'serviceLine'=>$c['service_line'],'otpPattern'=>$c['otp_pattern'],'otpAttribute'=>$c['otp_attribute'],'schoolName'=>$c['school_name'],'sendLimit'=>(int)$c['send_limit'],'quietFrom'=>$c['quiet_from'],'quietTo'=>$c['quiet_to'],'hasApiKey'=>$c['api_key']!=='','rules'=>$c['rules'],'cronToken'=>$c['cron_token']];}
function sms_save_config(array $body): array {
 $previous=sms_config();$api=trim((string)($body['apiKey']??''));if($api==='')$api=$previous['api_key'];$digits=fn(mixed $v)=>preg_replace('/\D/','',ascii_digits((string)$v));
 $rules=is_array($body['rules']??null)?array_replace_recursive(sms_rule_defaults(),$body['rules']):$previous['rules'];foreach($rules as &$rule){$rule['enabled']=(bool)($rule['enabled']??false);if(isset($rule['template']))$rule['template']=mb_substr(trim((string)$rule['template']),0,1000);}unset($rule);
 $config=['provider'=>'farazsms','enabled'=>(bool)($body['enabled']??false),'otp_enabled'=>(bool)($body['otpEnabled']??false),'api_key'=>$api,'line_number'=>$digits($body['lineNumber']??''),'service_line'=>$digits($body['serviceLine']??''),'otp_pattern'=>preg_replace('/[^A-Za-z0-9_-]/','',(string)($body['otpPattern']??'')),'otp_attribute'=>preg_replace('/[^A-Za-z0-9_]/','',(string)($body['otpAttribute']??'code'))?:'code','school_name'=>mb_substr(trim((string)($body['schoolName']??'دفتر کلاسی من')),0,120),'send_limit'=>max(1,min(500,(int)($body['sendLimit']??500))),'quiet_from'=>preg_match('/^\d{2}:\d{2}$/',(string)($body['quietFrom']??''))?(string)$body['quietFrom']:'21:00','quiet_to'=>preg_match('/^\d{2}:\d{2}$/',(string)($body['quietTo']??''))?(string)$body['quietTo']:'07:00','cron_token'=>$previous['cron_token']?:bin2hex(random_bytes(24)),'rules'=>$rules];
 school_require(!$config['enabled']||$config['api_key']!=='','برای فعال‌سازی پیامک، کلید API لازم است.');school_require(!$config['otp_enabled']||($config['enabled']&&$config['otp_pattern']!==''),'برای ورود پیامکی، سرویس فعال و کد پترن لازم است.');
 $target=__DIR__.'/sms-config.php';$temp=$target.'.tmp-'.bin2hex(random_bytes(5));school_require(file_put_contents($temp,"<?php\nreturn ".var_export($config,true).";\n",LOCK_EX)!==false,'ذخیره تنظیمات پیامک انجام نشد.');@chmod($temp,0600);school_require(rename($temp,$target),'ذخیره امن تنظیمات پیامک انجام نشد.');return $config;
}
function sms_phone(mixed $value): string {$phone=preg_replace('/\D/','',ascii_digits((string)$value));if(str_starts_with($phone,'98')&&strlen($phone)===12)$phone='0'.substr($phone,2);return preg_match('/^09\d{9}$/D',$phone)?$phone:'';}
function faraz_error_message(array $result): string {foreach(['message','messages','error'] as $key){$v=$result[$key]??null;if(is_string($v)&&trim($v)!=='')return trim($v);if(is_array($v))return implode('، ',array_filter(array_map('strval',$v)));}return 'فراز اس‌ام‌اس درخواست را نپذیرفت.';}
function faraz_success_message(array $result): string {foreach(['message','messages'] as $key){$v=$result[$key]??null;if(is_string($v)&&trim($v)!=='')return trim($v);if(is_array($v)){foreach($v as $item)if(is_scalar($item)&&trim((string)$item)!=='')return trim((string)$item);}}return 'درخواست توسط فراز اس‌ام‌اس پذیرفته شد.';}
function faraz_request(string $method,string $path,?array $payload=null,array $query=[],?array $overrideConfig=null,bool $requireEnabled=true): array {
 $c=$overrideConfig??sms_config();school_require((!$requireEnabled||!empty($c['enabled']))&&($c['api_key']??'')!=='',$requireEnabled?'سرویس پیامک فعال و پیکربندی نشده است.':'کلید API برای آزمایش اتصال وارد نشده است.');$url='https://api.iranpayamak.com'.$path.($query?'?'.http_build_query($query):'');$headers=['Accept: application/json','Api-Key: '.$c['api_key']];$body=$payload===null?'':json_encode($payload,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);if($payload!==null)$headers[]='Content-Type: application/json';
 $options=['http'=>['method'=>$method,'header'=>implode("\r\n",$headers),'ignore_errors'=>true,'timeout'=>25,'follow_location'=>0],'ssl'=>['verify_peer'=>true,'verify_peer_name'=>true]];if($payload!==null)$options['http']['content']=$body;
 $raw=@file_get_contents($url,false,stream_context_create($options));$status=0;foreach($http_response_header??[] as $header)if(preg_match('/^HTTP\/\S+\s+(\d{3})/',$header,$m))$status=(int)$m[1];
 school_require(is_string($raw),'ارتباط HTTPS با فراز اس‌ام‌اس برقرار نشد. تنظیمات دسترسی خروجی هاست را بررسی کنید.');$result=json_decode($raw,true);school_require(is_array($result),'پاسخ فراز اس‌ام‌اس معتبر نبود.');if($status<200||$status>=300)throw new InvalidArgumentException(faraz_error_message($result));return $result;
}
function sms_sender_line(bool $service=false): string {$c=sms_config();$line=$service&&$c['service_line']!==''?$c['service_line']:$c['line_number'];if($line==='')$line=$c['service_line'];school_require($line!=='','سرشماره ارسال در تنظیمات پیامک تعیین نشده است.');return $line;}
function faraz_send_pattern(string $phone,string $code): array {$c=sms_config();school_require((bool)$c['otp_enabled'],'ورود پیامکی غیرفعال است.');return faraz_request('POST','/ws/v1/sms/pattern',['code'=>$c['otp_pattern'],'attributes'=>[$c['otp_attribute']=>$code],'recipient'=>sms_phone($phone),'line_number'=>sms_sender_line(true),'number_format'=>'english']);}
function faraz_send_simple(array $phones,string $text,?string $schedule=null,bool $service=false): array {$c=sms_config();$phones=array_values(array_unique(array_filter(array_map('sms_phone',$phones))));$text=trim($text);school_require($phones!==[]&&$text!=='','شماره گیرنده و متن پیامک لازم است.');school_require(count($phones)<=$c['send_limit'],'تعداد گیرندگان از سقف تنظیم‌شده بیشتر است.');school_require(mb_strlen($text)<=1000,'متن پیامک حداکثر ۱۰۰۰ نویسه است.');$payload=['text'=>$text,'line_number'=>sms_sender_line($service),'recipients'=>$phones,'number_format'=>'english'];if($schedule)$payload['schedule']=$schedule;return faraz_request('POST','/ws/v1/sms/simple',$payload);}
function faraz_request_id(array $result): string {$data=$result['data']??'';if(is_scalar($data))return (string)$data;if(is_array($data))foreach(['id','request_id','message_id','bulk_id'] as $key)if(isset($data[$key])&&is_scalar($data[$key]))return (string)$data[$key];return '';}
function faraz_first_line(mixed $value): string {if(is_string($value)&&preg_match('/^\d{5,20}$/D',$value))return $value;if(is_array($value)){foreach(['line_number','number','from','sender'] as $key)if(isset($value[$key])&&is_scalar($value[$key])){$line=preg_replace('/\D/','',(string)$value[$key]);if(preg_match('/^\d{5,20}$/D',$line))return $line;}foreach($value as $child){$line=faraz_first_line($child);if($line!=='')return $line;}}return '';}
function sms_job_log(int $actorId,string $kind,string $text,array $phones,string $status,string $providerId='',string $error='',array $meta=[],?string $eventKey=null): int {$q=db()->prepare('INSERT INTO pdm_sms_jobs(actor_id,kind,event_key,message,recipients_count,status,provider_id,error_text,meta) VALUES(?,?,?,?,?,?,?,?,?)');$q->execute([$actorId?:null,$kind,$eventKey,$text,count($phones),$status,$providerId,mb_substr($error,0,1000),json_encode($meta,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR)]);$id=(int)db()->lastInsertId();$item=db()->prepare('INSERT INTO pdm_sms_recipients(job_id,phone,status) VALUES(?,?,?)');foreach($phones as $phone)$item->execute([$id,$phone,$status]);return $id;}
function sms_template(string $template,array $vars): string {return preg_replace_callback('/\{([a-z_]+)\}/',fn($m)=>(string)($vars[$m[1]]??$m[0]),$template);}
function sms_guardian(array $state,string $studentId): ?array {foreach($state['life']['contacts']??[] as $contact)if(($contact['group']??'')==='family'&&($contact['studentId']??'')===$studentId&&!empty($contact['consent'])&&sms_phone($contact['phone']??'')!=='')return $contact;return null;}
function sms_event_exists(string $key): bool {$q=db()->prepare('SELECT 1 FROM pdm_sms_jobs WHERE event_key=?');$q->execute([$key]);return (bool)$q->fetchColumn();}
function sms_send_automatic(int $actorId,string $kind,string $eventKey,string $phone,string $text,array $meta=[]): void {if(sms_event_exists($eventKey))return;try{$result=faraz_send_simple([$phone],$text,null,true);sms_job_log($actorId,$kind,$text,[$phone],'queued',faraz_request_id($result),'',$meta,$eventKey);}catch(Throwable $e){try{sms_job_log($actorId,$kind,$text,[$phone],'failed','',$e->getMessage(),$meta,$eventKey);}catch(Throwable $ignored){}}}
function sms_detect_events(array $before,array $after,int $actorId): void {
 $c=sms_config();if(!$c['enabled'])return;$rules=$c['rules'];$beforeDispatch=[];foreach($before['life']['dispatches']??[] as $x)$beforeDispatch[$x['sessionId']]=$x;
 if(!empty($rules['absence']['enabled']))foreach($after['life']['dispatches']??[] as $dispatch){$old=$beforeDispatch[$dispatch['sessionId']]??null;foreach($dispatch['rows']??[] as $row){if(($row['status']??'')!=='absent')continue;$was=$old?array_values(array_filter($old['rows']??[],fn($x)=>($x['id']??'')===($row['id']??'')&&($x['status']??'')==='absent')):[];if($was)continue;$contact=sms_guardian($after,(string)$row['id']);if(!$contact)continue;$text=sms_template($rules['absence']['template'],['student'=>$row['name']??'دانش‌آموز','date'=>$dispatch['date']??'','class'=>$dispatch['title']??'کلاس']);sms_send_automatic($actorId,'absence','absence:'.$dispatch['sessionId'].':'.$row['id'],sms_phone($contact['phone']),$text,['studentId'=>$row['id']]);}}
 $oldIncidents=array_column($before['d']['incidents']??[],null,'id');if(!empty($rules['discipline']['enabled']))foreach($after['d']['incidents']??[] as $incident){if(isset($oldIncidents[$incident['id']]))continue;$contact=sms_guardian($after,(string)$incident['studentId']);if(!$contact)continue;$student='دانش‌آموز';foreach($after['d']['students']??[] as $s)if(($s['id']??'')===($incident['studentId']??'')){$student=$s['name'];break;}$text=sms_template($rules['discipline']['template'],['student'=>$student,'title'=>$incident['title']??'گزارش انضباطی','date'=>$incident['date']??'']);sms_send_automatic($actorId,'discipline','discipline:'.$incident['id'],sms_phone($contact['phone']),$text,['studentId'=>$incident['studentId']]);}
 foreach($after['d']['finals']??[] as $key=>$final){if(($before['d']['finals'][$key]??null)===$final)continue;$parts=explode(':',(string)$key);if(count($parts)<3)continue;$studentId=array_pop($parts);$moduleIndex=(int)array_pop($parts);$courseId=implode(':',$parts);$course=null;foreach($after['d']['offerings']??[] as $o)if(($o['id']??'')===$courseId){$course=$o;break;}if(!$course)continue;$kind=($course['gradingMode']??'modular')==='annual'?'annual_grades':'module_grades';if(empty($rules[$kind]['enabled']))continue;$total=$final['total']??null;if($total===null&&isset($final['continuous'])&&isset($final['competency']))$total=(float)$final['continuous']+5*(float)$final['competency'];if($total===null)continue;$contact=sms_guardian($after,$studentId);if(!$contact)continue;$student='دانش‌آموز';foreach($after['d']['students']??[] as $s)if(($s['id']??'')===$studentId){$student=$s['name'];break;}$module=$course['modules'][$moduleIndex]['name']??'ارزشیابی نهایی';$summary=(string)$total.' از ۲۰';$text=sms_template($rules[$kind]['template'],['student'=>$student,'module'=>$module,'course'=>$course['name']??'درس','summary'=>$summary]);sms_send_automatic($actorId,$kind,$kind.':'.sha1($key.json_encode($final)),$contact['phone'],$text,['studentId'=>$studentId,'courseId'=>$courseId,'module'=>$moduleIndex]);}
}
